// src/tools/map.ts
function overview(api, scn) {
  const info = api.document.info();
  const players = api.settings.players().map((p) => ({
    player: p.slot + 1,
    type: p.typeName,
    race: p.raceName,
    ...p.force !== null ? { force: p.force + 1 } : {},
    units: 0
  }));
  for (const u of scn.units) if (players[u.owner]) players[u.owner].units++;
  const locations = scn.locations.reduce((n, _, i) => n + (locationInUse(scn, i) ? 1 : 0), 0);
  return {
    name: info?.name,
    description: info?.description,
    fileName: info?.fileName,
    widthTiles: scn.width,
    heightTiles: scn.height,
    tileset: info?.tileset,
    version: info?.version,
    modified: info?.modified,
    viewOnly: info?.viewOnly,
    graphicsLoaded: api.tileset.isLoaded(),
    players,
    forces: api.settings.forces().map((f) => ({
      force: f.force + 1,
      name: f.name,
      players: f.players.map((s) => s + 1),
      allied: f.allied,
      alliedVictory: f.alliedVictory,
      sharedVision: f.sharedVision,
      randomStart: f.randomStart
    })),
    counts: {
      units: scn.units.length,
      sprites: scn.sprites.length,
      doodads: scn.doodads.length,
      locations,
      triggers: api.triggers.list().length,
      briefingTriggers: api.triggers.briefing().length,
      strings: api.query.strings().filter((s, i) => i > 0 && s).length
    },
    startLocations: api.query.startLocations().map((s) => ({ player: s.owner + 1, tile: [s.tx, s.ty] })),
    lastUndo: api.document.history().undo
  };
}
function mapState(api) {
  const scn = api.document.scenario();
  if (!scn) return "No map is open.";
  const info = api.document.info();
  const sel = {
    units: api.selection.units().length,
    locations: api.selection.locations().map((i) => i + 1),
    sprites: api.selection.sprites().length,
    doodads: api.selection.doodads().length,
    markedArea: api.selection.markedArea(),
    layer: api.selection.layer()
  };
  const parts = [
    `Map "${info?.name ?? ""}"${info?.fileName ? ` (${info.fileName})` : ""}: ${scn.width}\xD7${scn.height} tiles, ${info?.tileset}, ${scn.units.length} units, ${api.triggers.list().length} triggers${info?.modified ? ", unsaved changes" : ""}${info?.viewOnly ? ", VIEW ONLY" : ""}.`,
    `Tileset graphics ${api.tileset.isLoaded() ? "loaded" : "not loaded"}.`,
    `Visible on screen: tiles ${json(roundRect(api.view.visible()))}. Active layer: ${sel.layer}.`
  ];
  const picked = [
    sel.units ? `${sel.units} unit(s)` : "",
    sel.locations.length ? `location(s) ${sel.locations.join(", ")}` : "",
    sel.sprites ? `${sel.sprites} sprite(s)` : "",
    sel.doodads ? `${sel.doodads} doodad(s)` : "",
    sel.markedArea ? `marked area ${json(sel.markedArea)}` : ""
  ].filter(Boolean);
  if (picked.length) parts.push(`Selected: ${picked.join(", ")} (get_selection lists them).`);
  return parts.join("\n");
}
async function base64(blob) {
  const bytes = new Uint8Array(await blob.arrayBuffer());
  let s = "";
  for (let i = 0; i < bytes.length; i += 32768) s += String.fromCharCode(...bytes.subarray(i, i + 32768));
  return btoa(s);
}
async function schematic(api, scn, rect, ppt, locations) {
  const w = (rect.x1 - rect.x0) * ppt;
  const h = (rect.y1 - rect.y0) * ppt;
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const g = canvas.getContext("2d");
  if (!g) return null;
  const X2 = (px) => (px / TILE - rect.x0) * ppt;
  const Y = (py) => (py / TILE - rect.y0) * ppt;
  g.fillStyle = "#1c1f24";
  g.fillRect(0, 0, w, h);
  g.strokeStyle = "rgba(255,255,255,0.08)";
  g.lineWidth = 1;
  for (let t2 = Math.ceil(rect.x0 / 8) * 8; t2 <= rect.x1; t2 += 8) {
    g.beginPath();
    g.moveTo((t2 - rect.x0) * ppt + 0.5, 0);
    g.lineTo((t2 - rect.x0) * ppt + 0.5, h);
    g.stroke();
  }
  for (let t2 = Math.ceil(rect.y0 / 8) * 8; t2 <= rect.y1; t2 += 8) {
    g.beginPath();
    g.moveTo(0, (t2 - rect.y0) * ppt + 0.5);
    g.lineTo(w, (t2 - rect.y0) * ppt + 0.5);
    g.stroke();
  }
  if (locations) {
    g.font = `${Math.max(9, Math.min(14, ppt * 1.5))}px sans-serif`;
    scn.locations.forEach((l, i) => {
      if (!locationInUse(scn, i)) return;
      g.strokeStyle = "rgba(90,200,255,0.9)";
      g.fillStyle = "rgba(90,200,255,0.12)";
      g.fillRect(X2(l.left), Y(l.top), X2(l.right) - X2(l.left), Y(l.bottom) - Y(l.top));
      g.strokeRect(X2(l.left), Y(l.top), X2(l.right) - X2(l.left), Y(l.bottom) - Y(l.top));
      g.fillStyle = "rgba(160,225,255,1)";
      g.fillText(stringOf(api, l.nameIndex) || `Location ${i + 1}`, X2(l.left) + 2, Y(l.top) + 11);
    });
  }
  for (const u of scn.units) {
    const size = api.palette.unitSize(u.unitId);
    const isStart = u.unitId === api.consts.unit.startLocation;
    g.fillStyle = api.palette.playerColor(u.owner);
    if (isStart) {
      const s = Math.max(6, ppt * 2);
      g.fillRect(X2(u.x) - s / 2, Y(u.y) - s / 2, s, s);
      g.fillStyle = "#fff";
      g.fillText(String(u.owner + 1), X2(u.x) - 3, Y(u.y) + 4);
      continue;
    }
    const rw = Math.max(2, size.width / TILE * ppt);
    const rh = Math.max(2, size.height / TILE * ppt);
    if (size.building) g.fillRect(X2(u.x) - rw / 2, Y(u.y) - rh / 2, rw, rh);
    else {
      g.beginPath();
      g.arc(X2(u.x), Y(u.y), Math.max(1.5, rw / 2), 0, Math.PI * 2);
      g.fill();
    }
  }
  return new Promise((resolve) => canvas.toBlob((b) => resolve(b), "image/png"));
}
function sections(text) {
  const out = [];
  const re2 = /^(#{1,4}) (.+)$/gm;
  let m;
  let fence = false;
  const lines = text.split("\n");
  let offset = 0;
  for (const line of lines) {
    if (line.startsWith("```")) fence = !fence;
    re2.lastIndex = 0;
    if (!fence && (m = re2.exec(line))) out.push({ level: m[1].length, heading: m[2].trim(), start: offset, end: text.length });
    offset += line.length + 1;
  }
  for (let i = 0; i < out.length; i++) {
    const next = out.slice(i + 1).find((s) => s.level <= out[i].level);
    if (next) out[i].end = next.start;
  }
  return out;
}
